'use strict';
/* Вращающийся земной шар — Claude Sonnet 5.5
 * Canvas 2D, без библиотек. Планета целиком процедурная/зашитая в код:
 *  - карта суши: контуры материков (lon/lat) -> растр -> доменный варп шумом (фрактальные берега);
 *  - биомы, горы, шельф, лёд, огни городов, облака с циклонами — всё считается при старте;
 *  - рендер: программный ray-cast сферы в ImageData (билинейная выборка, LUT освещения,
 *    закатное покраснение, мягкий терминатор, тени облаков, блик Солнца, атмосфера).
 * Чистая логика экспортируется через module.exports (dual-mode) для проверки в node.
 */

const TW = 2048, TH = 1024, HWD = 1024, HHD = 512, TMASK = TW - 1;
const PI = Math.PI, TAU = PI * 2, DEG = PI / 180;

function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function clamp(x, a, b) { return x < a ? a : (x > b ? b : x); }
function sstep(a, b, x) { let t = (x - a) / (b - a); t = t < 0 ? 0 : (t > 1 ? 1 : t); return t * t * (3 - 2 * t); }
function mix(a, b, t) { return a + (b - a) * t; }

/* ---------- 3D value noise ---------- */
function makeNoise(seed) {
  const rnd = mulberry32(seed);
  const P = new Uint8Array(512), V = new Float32Array(256), p0 = new Uint8Array(256);
  for (let i = 0; i < 256; i++) { p0[i] = i; V[i] = rnd(); }
  for (let i = 255; i > 0; i--) { const j = (rnd() * (i + 1)) | 0; const t = p0[i]; p0[i] = p0[j]; p0[j] = t; }
  for (let i = 0; i < 512; i++) P[i] = p0[i & 255];
  return function (x, y, z) {
    const xf = Math.floor(x), yf = Math.floor(y), zf = Math.floor(z);
    const fx = x - xf, fy = y - yf, fz = z - zf;
    const X = xf & 255, Y = yf & 255, Z = zf & 255;
    const u = fx * fx * fx * (fx * (fx * 6 - 15) + 10);
    const v = fy * fy * fy * (fy * (fy * 6 - 15) + 10);
    const w = fz * fz * fz * (fz * (fz * 6 - 15) + 10);
    const A = P[X] + Y, AA = P[A] + Z, AB = P[A + 1] + Z, B = P[X + 1] + Y, BA = P[B] + Z, BB = P[B + 1] + Z;
    const v000 = V[P[AA]], v100 = V[P[BA]], v010 = V[P[AB]], v110 = V[P[BB]];
    const v001 = V[P[AA + 1]], v101 = V[P[BA + 1]], v011 = V[P[AB + 1]], v111 = V[P[BB + 1]];
    const x00 = v000 + (v100 - v000) * u, x10 = v010 + (v110 - v010) * u;
    const x01 = v001 + (v101 - v001) * u, x11 = v011 + (v111 - v011) * u;
    const y0 = x00 + (x10 - x00) * v, y1 = x01 + (x11 - x01) * v;
    return y0 + (y1 - y0) * w;
  };
}
function fbm(n, x, y, z, oct, gain) {
  let a = 1, s = 0, t = 0;
  for (let o = 0; o < oct; o++) {
    s += a * n(x, y, z); t += a; a *= gain;
    x = x * 2.03 + 17.1; y = y * 2.03 + 9.7; z = z * 2.03 + 4.3;
  }
  return s / t;
}
function ridged(n, x, y, z, oct) {
  let a = 1, s = 0, t = 0;
  for (let o = 0; o < oct; o++) {
    const q = n(x, y, z);
    s += a * (1 - Math.abs(2 * q - 1)); t += a; a *= 0.5;
    x = x * 2.1 + 5.3; y = y * 2.1 + 11.9; z = z * 2.1 + 2.7;
  }
  return s / t;
}

