      if (r2 >= 1) { ax = X / r; ay = Y / r; az = 0; } else az = Math.sqrt(1 - r2);
      const px = ax * ex[0] + ay * ex[1] + az * ex[2];
      const py = ax * ey[0] + ay * ey[1] + az * ey[2];
      const pz = ax * ez[0] + ay * ez[1] + az * ez[2];
      const lat = Math.asin(clamp(py, -1, 1)), lon = Math.atan2(px, pz);
      let u = lon / TAU * tw - 0.5; u = ((u % tw) + tw) % tw;
      const v = (0.5 - lat / PI) * th - 0.5;
      let iv = Math.floor(v), f = v - iv;
      if (iv < 0) { iv = 0; f = 0; } else if (iv > th - 2) { iv = th - 2; f = 1; }
      const k = y * S + x;
      nx[k] = ax; ny[k] = ay; nz[k] = az; u0[k] = u; rw[k] = iv * tw; fv[k] = Math.min(255, (f * 256) | 0); cov[k] = (c * 255 + 0.5) | 0;
